import { searchPlugin } from '@payloadcms/plugin-search'
import { multiTenantPlugin } from '@payloadcms/plugin-multi-tenant'
import { mcpPlugin } from '@payloadcms/plugin-mcp'
import { UnauthorizedError } from 'payload'
import { handle } from '@uuidna/qpu/mcp'
import { qpuEcommerce } from './payload.qpu.ecommerce'
import { Qpu } from './blocks/Qpu/config'
import { qpuMcpTools, qpuMcpResources, qpuServerInfo } from './payload.qpu.mcp'

export const qpuBlocks = [Qpu] // beside the site's 30 blocks; referenced as 'qpu' in every layout
export const qpuPlugins = [
  // the ecommerce plugin first: it creates products, carts, orders, transactions and addresses, which the multi-tenant plugin scopes (measured: placed after, the plugin warns of missing collections)
  qpuEcommerce, // the licence catalogue sold through Payload's own ecommerce plugin with its Stripe adapter: the API from the config
  searchPlugin({ collections: ['pages', 'posts'] }),
  // enterprise tenants from the configs: four scoped collections, a super admin by the admin role (never everyone), tenant roles on every user's tenants row, tenants readable by all
  multiTenantPlugin({ collections: { pages: {}, entries: {}, products: {}, orders: {} }, tenantsSlug: 'tenants', userHasAccessToAllTenants: (user) => Array.isArray((user as { roles?: string[] }).roles) && (user as { roles: string[] }).roles.includes('admin'), tenantsArrayField: { includeDefaultField: true, rowFields: [{ name: 'roles', type: 'select', hasMany: true, defaultValue: ['viewer'], options: ['tenant-admin', 'editor', 'viewer'] }] } } as never), // scopes: uuidna, psg, ceci over pages, entries, products, orders; roles tenant-admin, editor, viewer
  // only Payload: the handler's tools served by the MCP plugin (the server named qpu), the Worker's /mcp replaced
  mcpPlugin({ collections: {"pages":{"description":"the site's pages: the use cases and the gates (the competition gates carry the competitors and the theorems), each a qpu block; edits carry editBase (the collision precondition)","enabled":{"find":true,"create":true,"update":true,"delete":false}},"forms":{"description":"the forms: \"Request an app\" among them","enabled":{"find":true,"create":false,"update":false,"delete":false}},"form-submissions":{"description":"a submission of \"Request an app\" generates the app (the bundle into media, the licence at the checkout)","enabled":{"find":true,"create":true,"update":false,"delete":false}},"media":{"description":"the uploads: a generated app is a JSON file here (every file with its address, the bundle address, the price, the order)","enabled":{"find":true,"create":false,"update":false,"delete":false}},"products":{"description":"the licence catalogue as products of the ecommerce plugin","enabled":{"find":true,"create":false,"update":false,"delete":false}},"carts":{"description":"the carts of the ecommerce plugin: a licence product put in one is bought at its checkout","enabled":{"find":true,"create":true,"update":true,"delete":false}},"orders":{"description":"the orders the checkout wrote","enabled":{"find":true,"create":false,"update":false,"delete":false}},"tenants":{"description":"the tenants by host; settings are the plugin options a tenant configures (merged into every qpu block call under its hosts)","enabled":{"find":true,"create":false,"update":true,"delete":false}},"entries":{"description":"the docket: content-addressed entries (calls, licences, signals, messages); immutable — the editors' channel: a message or a signal is an entry created here, read by find where from = page:<slug>","enabled":{"find":true,"create":true,"update":false,"delete":false}},"posts":{"description":"the site's posts","enabled":{"find":true,"create":true,"update":true,"delete":false}},"search":{"description":"the search plugin's index","enabled":{"find":true,"create":false,"update":false,"delete":false}},"redirects":{"description":"the redirects plugin's rules","enabled":{"find":true,"create":false,"update":false,"delete":false}},"variants":{"description":"the ecommerce plugin's variants","enabled":{"find":true,"create":false,"update":false,"delete":false}},"transactions":{"description":"the ecommerce plugin's transactions: the payment ledger","enabled":{"find":true,"create":false,"update":false,"delete":false}},"addresses":{"description":"the ecommerce plugin's addresses","enabled":{"find":true,"create":false,"update":false,"delete":false}},"users":{"description":"the users: who edits; keys never travel","enabled":{"find":true,"create":false,"update":false,"delete":false}}}, mcp: { tools: qpuMcpTools, resources: qpuMcpResources, serverOptions: { serverInfo: qpuServerInfo } }, overrideAuth: async (req: any, getDefault: () => Promise<any>) => {
    // tenants as namespaces: a request naming x-qpu-namespace is narrowed to that one tenant, as the payload tool decides (textbook_namespace_narrows)
    const settings = await getDefault(); const ns = req.headers.get('x-qpu-namespace'); if (!ns) return settings
    const tenants = (await req.payload.find({ collection: 'tenants', where: { namespace: { equals: ns } }, limit: 1, depth: 0, overrideAccess: true })).docs.map((x: any) => ({ id: String(x.id), namespace: x.namespace }))
    const user = settings.user; const rows = (user.tenants ?? []).map((r: any) => ({ tenant: String(typeof r.tenant === 'object' ? r.tenant?.id : r.tenant), roles: r.roles ?? [] }))
    const n = (handle({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: 'payload', arguments: { namespace: { narrow: { requested: ns, tenants, user: { roles: user.roles ?? [], tenants: rows } } } } } }) as any).result?.structuredContent
    if (!n?.allowed) throw new UnauthorizedError()
    user.roles = n.roles; user.tenants = n.rows; return settings
  } } as never), // the tools and the ui:// resources of every tool (MCP Apps) through the plugin; an API key per user authorises a client, narrowed to the namespace a request names
]
